{
  "requirement_id": "REQ-009",
  "summary": "Implement task search API endpoint GET /api/projects/{pid}/tasks?q=<text> with case-insensitive substring matching on titles, treating special wildcard characters literally, and supporting combination with status filtering and pagination.",
  "acceptance_criteria": [
    "Search is case-insensitive for ASCII characters (e.g., q=login matches Fix Login Bug).",
    "Special characters '%' and '_' are treated as literal characters, not wildcards.",
    "Can be used simultaneously with status filtering and pagination."
  ]
}

